import { course, landingHref, statusNote } from "../course";

/**
 * The built cases. Each has its own page, site/case-<id>.qmd, generated by
 * `tutor case site` from projects/<id>/case/case.toml. site.test.ts checks
 * this list against those pages, so a new case page cannot go unlisted.
 */
export const BUILT_CASES: { id: string; course: string; title: string; summary: string }[] = [
  {
    id: "odeint",
    course: "scicomp",
    title: "Long orbits: Dormand–Prince 5(4) or a symplectic method?",
    summary:
      "Write Dormand–Prince 5(4) from its tableau and verify it, then measure which integrator keeps a Kepler " +
      "orbit's energy error under budget over 1000 orbits for less work (milestone M4).",
  },
];

export const caseHref = (id: string) => `case-${id}.html`;

/**
 * The cases index: what a case project is, the built cases (each linking its
 * page), and the cases each course still plans, read from the course
 * manifests' outcomes ("planned").
 */
export function CasesView() {
  const byCourse = course.courses
    .map((c) => ({ c, planned: [...new Set(c.outcomes.flatMap((o) => o.planned))] }))
    .filter((g) => g.planned.length > 0);

  return (
    <div className="jt-grid" style={{ gap: "1.1rem" }}>
      <section className="jt-panel jt-pad">
        <div className="jt-eyebrow">Ready</div>
        {BUILT_CASES.map((k) => {
          const c = course.courses.find((x) => x.id === k.course);
          return (
            <div key={k.id} style={{ marginTop: "0.4rem" }}>
              <h3 style={{ margin: "0.25rem 0" }}><a href={caseHref(k.id)}>{k.title}</a></h3>
              <p style={{ maxWidth: "48rem", margin: "0.25rem 0" }}>{k.summary}</p>
              {c && <div className="jt-muted jt-small">Course: <a href={landingHref(c.id)}>{c.title}</a></div>}
            </div>
          );
        })}
        <p style={{ maxWidth: "48rem", marginBottom: 0 }}>
          Its software checks are built and verified. Its pilot with learners has not been run yet, so nothing here
          is evidence that it teaches well. Everything further down is planned (cases, capstones and the full
          programs that end each course): it is listed because a course outcome is waiting for it, not because it
          exists.
        </p>
      </section>

      <section className="jt-panel jt-pad">
        <div className="jt-eyebrow">What a case is</div>
        <p style={{ maxWidth: "48rem" }}>
          A case starts from a scientific question and a quantity of interest with a required accuracy. You work
          through the same eight steps each time, with less scaffolding in later cases: state the question; estimate
          the answer from scales before any code runs; write down the model and its assumptions; choose a method and
          justify it; verify the code; validate the model; quantify uncertainty; report only what the evidence
          supports.
        </p>
        <p style={{ maxWidth: "48rem", marginBottom: 0 }}>
          Software checks part of it: hidden acceptance tests, mutants, and a claim checker that every number in
          your report equals what your own code computes. <strong>No software grades the reasoning.</strong> That
          part is assessed with a published rubric, by yourself, a peer or an instructor.
        </p>
      </section>

      {byCourse.map(({ c, planned }) => (
        <section key={c.id} className="jt-panel jt-pad">
          <div className="jt-eyebrow">
            <a href={landingHref(c.id)}>{c.title}</a>{statusNote(c) && <> · <span className="jt-chip advice">{statusNote(c)}</span></>}
          </div>
          <ul style={{ margin: "0.4rem 0 0" }}>
            {planned.map((p) => <li key={p}>{p} <span className="jt-chip">planned</span></li>)}
          </ul>
        </section>
      ))}
    </div>
  );
}
